    /* 이 프린트 포맷 전체를 위한 스타일 블록 */
    .door-print-wrapper {
        font-family: sans-serif; /* 폰트를 지정하여 일관성을 높입니다 (선택 사항) */
    }
    .door-print-wrapper th,
    .door-print-wrapper td,
    .door-print-wrapper div {
        font-size: 10pt !important;
        vertical-align: middle !important; /* 모든 셀 수직 중앙 정렬 */
