        margin: 0;
    }
    .door-print-wrapper .sub-title {
        font-size: 10pt !important;
        font-weight: bold;
        display: inline; /* h5 태그의 동작을 유지 */
        margin: 0;
    }
</style>

<div class="door-print-wrapper">
{%- set previous_hw_spec = namespace(value=None) -%}
{%- set is_table_open = namespace(value=False) -%} {# 테이블이 열려있는지 상태를 추적 #}

{%- set door_row_counter = namespace(value=0) -%}
{%- for row in doc.door_cover -%}
    {%- if row.product_section == "Door" -%}
        {%- set door_row_counter.value = door_row_counter.value + 1 -%}
        {# --- (hw_spec_doc, found_leaves, show_header_and_hw_details, hr 출력 등 이전 로직들) --- #}
        {%- set outer_loop_index = loop.index0 -%}

        {%- set hw_spec_doc = None -%}
        {%- if row.door_hw_spec -%}
            {%- set hw_spec_doc = frappe.get_doc("Door Hardware Spec", row.door_hw_spec) -%}
        {%- endif -%}

        {%- set found_leaves = namespace(items=[]) -%}
        {%- for next_item in doc.door_cover[outer_loop_index + 1:] -%}
            {%- if next_item.product_section == 'Leaf' -%}
                {%- if (row.door_set_type == 'Pair' and found_leaves.items|length < 2) or (row.door_set_type == 'Single' and found_leaves.items|length < 1) -%}
                    {%- set __ = found_leaves.items.append(next_item) -%}
                {%- endif -%}
            {%- endif -%}
        {%- endfor -%}

        {%- set show_header_and_hw_details = True -%}
        {%- if not loop.first and row.door_hw_spec == previous_hw_spec.value and row.door_hw_spec is not none -%}
            {%- set show_header_and_hw_details = False -%}
        {%- endif -%}

        {%- if loop.first or row.door_hw_spec != previous_hw_spec.value -%}
            {%- if not loop.first and previous_hw_spec.value is not none -%}
                {# 이전 그룹의 "세 번째 줄" 테이블 닫기 #}
                {%- if is_table_open.value -%}
                    </table>
                    {%- set is_table_open.value = False -%}
                    <div style="page-break-before: always;"></div>
                {%- endif -%}
                <hr>
            {%- endif -%}
        {%- endif -%}

        {%- if show_header_and_hw_details -%}
            {# <!-- (첫 번째 줄 및 두 번째 줄 HTML 내용) --> #}
            <div style="width: 100%;">
                <!-- 첫 번째 줄 -->
                <div style="display: flex; justify-content: space-between; align-items: center; width: 100%;">
                    <div style="flex-basis: 33.33%; text-align: left;"><span class="main-title">{{ row.product_type }}</span></div>
                    <div style="flex-basis: 33.33%; text-align: center;">Project: <span class="main-title" style="margin-left: 5px;">{{ doc.project_name }}</span></div>
                    <div style="flex-basis: 33.33%; text-align: right;"></div>
                </div>
                <!-- 두 번째 줄 -->
                <div>
                    {% set prefix_to_remove = doc.project + "-" %}
                    Hardware Spec: <span class="sub-title" style="margin-left: 5px;">{{ hw_spec_doc.hw_spec_code }}</span>
                </div>
            </div>
            <div>
                {# <!-- (HW 스펙 테이블들) --> #}
                {%- if hw_spec_doc -%}
                <table class="table table-bordered table-condensed" style="width: 40%; border: 1px solid black;">
                    <tbody>
                        <tr>
                            <th style="border: 1px solid black; width: 140px; text-align: center;">Mortise</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.mortise }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Handle</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.handle }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Key Cylinder</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.key_cylinder }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Lockset Height</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.lockset_h }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Door Closer</th>
                            <td style="border: 1px solid black; text-align: center;">{%- if hw_spec_doc.door_closer == "Y" and hw_spec_doc.door_closer_name -%}{{ hw_spec_doc.door_closer_name }}{%- elif hw_spec_doc.door_closer == "Y" -%}Y{%- else -%}N{%- endif -%}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">AL. Strip</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.al_strip }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Auto Drop Seal</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.auto_drop_seal }}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Hinge</th>
                            <td style="border: 1px solid black; text-align: center;">{%- if hw_spec_doc.hinge_type == "Pivot" -%} {{hw_spec_doc.hinge_type}} {%- if hw_spec_doc.pivot -%} &nbsp&nbsp|&nbsp&nbsp{{ hw_spec_doc.pivot }}{%- endif -%} {%- if row.hinge_num -%}&nbsp&nbsp|&nbsp&nbsp{{row.hinge_num}} EA{%- endif -%} {%- else -%} {{hw_spec_doc.hinge_type}} {%- endif -%}
                            </td>
                        </tr>
                    </tbody>
                </table>
                {%- endif -%}
                <table class="table table-bordered table-condensed" style="width: 40%; border: 1px solid black;">
                    <tbody>
                        <tr>
                            <th style="border: 1px solid black; width: 140px; text-align: center;">Security &<br>Access Control</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.security_access_control if hw_spec_doc.security_access_control else "N"}}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Wiring Device</th>
                            <td style="border: 1px solid black; text-align: center;">{{ hw_spec_doc.wiring if hw_spec_doc.wiring else "N" }}
                        </td>
                        </tr>
                    </tbody>
                </table>
                <div {% if not row.is_pair_door %}style="visibility: hidden;"{% endif %}>
                <table class="table table-bordered table-condensed" style="width: 40%;">
                    <tbody>
                        <tr>
                            <th style="border: 1px solid black; width: 140px; text-align: center;">Dummy-Pair</th>
                            <td style="border: 1px solid black; text-align: center;">{%- if hw_spec_doc.dummy == "Y" and hw_spec_doc.dummy_for_pair -%}{{ hw_spec_doc.dummy_for_pair }}{%- elif hw_spec_doc.dummy == "Y" -%}Y{%- else -%}N{%- endif -%}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Inactive<br>Door Closer</th>
                            <td style="border: 1px solid black; text-align: center;">
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Inactive<br>Auto Drop Seal</th>
                            <td style="border: 1px solid black; text-align: center;">{%- if hw_spec_doc.inactive_leaf == "Y" %}Y{% else %}N{% endif -%}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Flush Bolt</th>
                            <td style="border: 1px solid black; text-align: center;">{%- if hw_spec_doc.flush_bolt == "Y" %}Y{% else %}N{% endif -%}
                            </td>
                        </tr>
                        <tr>
                            <th style="border: 1px solid black; text-align: center;">Long Flush Bolt</th>
                            <td style="border: 1px solid black; text-align: center;">
                            </td>
                        </tr>
                    </tbody>
                </table>
                </div>
            </div>
        {%- endif -%}

        {# "세 번째 줄" 테이블 로직 #}
        {%- if loop.first or row.door_hw_spec != previous_hw_spec.value -%}
            {%- set door_row_counter.value = 1 -%}
            <table class="table table-bordered" style="text-align: center; border: 1px solid black;">
                <thead>
                    <tr>
                        <th style="border: 1px solid black;">No</th>
                        <th style="border: 1px solid black;" colspan="2">Keyword</th>
                        <th style="border: 1px solid black;">Size</th>
                        <th style="border: 1px solid black;">Qty</th>
                        <th style="border: 1px solid black;">Remark</th>
                    </tr>
                </thead>
            {%- set is_table_open.value = True -%} {# 테이블이 열렸음을 표시 #}
        {%- endif -%}

        {# 항상 tbody와 그 내용을 출력 (같은 테이블에 이어서 추가됨) #}
        <tbody style="border: 1px solid black;">
            <tr>
                <td style="border: 1px solid black;" rowspan="2">{{ door_row_counter.value }}</td>
                <td style="border: 1px solid black;" colspan="2">{{ row.product_keyword }}</td>
                <td style="border: 1px solid black;" rowspan="2">
                    <table class="table" style="width: 100%; margin:0px !important; border:0px !important;">
                        <tbody style="border:0px !important;">
                            {%- if row.width -%}
                            <tr>
                                <td style="border:0px !important; text-align: left !important;">Unit W</td>
                                <td style="border:0px !important; text-align: center;">=</td>
                                <td style="border:0px !important; text-align: center;">{{ "{:g}".format(row.width) }}</td>
                            </tr>
                            {%- endif -%}

                            {%- if row.ch -%}
                            <tr>
                                <td style="border:0px !important; text-align: left !important;">CH</td>
                                <td style="border:0px !important; text-align: center;">=</td>
                                <td style="border:0px !important; text-align: center;">{{ "{:g}".format(row.ch) }}</td>
                            </tr>
                            {%- endif -%}

